BEGIN;

-- ---------- 1) NÂNG CẤP SCHEMA ----------
ALTER TABLE products  ADD COLUMN IF NOT EXISTS excerpt       text DEFAULT '';
ALTER TABLE products  ADD COLUMN IF NOT EXISTS content       text DEFAULT '';
ALTER TABLE products  ADD COLUMN IF NOT EXISTS status        text DEFAULT 'published';
ALTER TABLE products  ADD COLUMN IF NOT EXISTS link_url      text DEFAULT '';
ALTER TABLE products  ADD COLUMN IF NOT EXISTS category_id   bigint;
ALTER TABLE products  ADD COLUMN IF NOT EXISTS updated_at    timestamptz DEFAULT now();
ALTER TABLE partners  ADD COLUMN IF NOT EXISTS slug          text DEFAULT '';
ALTER TABLE partners  ADD COLUMN IF NOT EXISTS excerpt       text DEFAULT '';
ALTER TABLE partners  ADD COLUMN IF NOT EXISTS content       text DEFAULT '';
ALTER TABLE partners  ADD COLUMN IF NOT EXISTS thumbnail_url text DEFAULT '';
ALTER TABLE projects  ADD COLUMN IF NOT EXISTS status        text DEFAULT 'published';

-- ---------- 2) DỌN SLUG RỖNG/TRÙNG TRƯỚC KHI TẠO UNIQUE INDEX ----------
UPDATE posts SET slug = 'auto-' || id WHERE slug IS NULL OR btrim(slug) = '';
UPDATE posts a SET slug = a.slug || '-' || a.id
  WHERE EXISTS (SELECT 1 FROM posts b WHERE b.slug = a.slug AND b.id < a.id);
CREATE UNIQUE INDEX IF NOT EXISTS posts_slug_uidx ON posts (slug);

UPDATE products SET slug = 'auto-' || id WHERE slug IS NULL OR btrim(slug) = '';
UPDATE products a SET slug = a.slug || '-' || a.id
  WHERE EXISTS (SELECT 1 FROM products b WHERE b.slug = a.slug AND b.id < a.id);
CREATE UNIQUE INDEX IF NOT EXISTS products_slug_uidx ON products (slug);

UPDATE projects SET slug = 'auto-' || id WHERE slug IS NULL OR btrim(slug) = '';
UPDATE projects a SET slug = a.slug || '-' || a.id
  WHERE EXISTS (SELECT 1 FROM projects b WHERE b.slug = a.slug AND b.id < a.id);
CREATE UNIQUE INDEX IF NOT EXISTS projects_slug_uidx ON projects (slug);

UPDATE partners SET slug = 'auto-' || id WHERE slug IS NULL OR btrim(slug) = '';
UPDATE partners a SET slug = a.slug || '-' || a.id
  WHERE EXISTS (SELECT 1 FROM partners b WHERE b.slug = a.slug AND b.id < a.id);
CREATE UNIQUE INDEX IF NOT EXISTS partners_slug_uidx ON partners (slug);

